using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Research Agent – searches the web, takes notes, then summarises findings.
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"🔍 Research Agent – topic: \"{topic}\"\n");

// --- Build the chat client pipeline (OpenAI ➜ function-invoking wrapper) ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Register tools ---
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns a list of result titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("Short heading for the note")] string heading,
         [Description("Content of the note")] string content) =>
        {
            notebook.Add(heading, content);
            return $"Note saved: {heading}";
        },
        "save_note",
        "Save a research note. Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieve all notes saved so far."),
};

// --- Build the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic you must:
        1. Search the web (2-3 varied queries) to gather information.
        2. Save the key findings as notes using the save_note tool.
        3. After gathering enough information, retrieve your notes and produce a
           well-structured summary with sections, key facts, and source URLs.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches a topic by searching the web and summarising findings.",
    tools: tools);

// --- Run ---
var session = new AgentSession();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session);

Console.WriteLine("\n══════════════════════════════════════════════════════════");
Console.WriteLine("  📝  RESEARCH SUMMARY");
Console.WriteLine("══════════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

