// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Simulated web search using DuckDuckGo Instant Answer API (no key needed).</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
            using var doc = await Http.GetFromJsonAsync<JsonDocument>(url);
            var root = doc!.RootElement;

            var results = new List<string>();

            // Abstract
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                var absUrl = root.GetProperty("AbstractURL").GetString();
                results.Add($"[Summary] {abs}\n  Source: {absUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var href = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add($"• {text}\n  URL: {href}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Simple in-memory notebook for the agent to store research notes.</summary>
class Notebook
{
    private readonly List<(string Heading, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string heading, string content) =>
        _notes.Add((heading, content, DateTime.UtcNow));

    public string GetAll() =>
        _notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n---\n",
                _notes.Select((n, i) => $"[{i + 1}] {n.Heading}\n{n.Content}"));
}

